from PIL import Image
img = Image.open('/app/output/final_poster.png')

# Header area - scan for bright pixels around where title should be
print("=== HEADER SCAN (title area) ===")
for y in range(60, 150, 4):
    px = img.getpixel((540, y))
    s = sum(px)
    if s > 200:
        print(f"  y={y:3d}: sum={s:3d}  TEXT")

# Metric 3 ("10") area
print("\n=== METRIC 3 ('10') SCAN ===")
for x in range(60, 120, 4):
    for y in range(325, 360, 4):
        px = img.getpixel((x, y))
        s = sum(px)
        if s > 400:
            print(f"  ({x},{y}): sum={s:3d} TEXT")

# Row 1 stars area
print("\n=== ROW 1 STARS SCAN ===")
for x in range(680, 745, 3):
    for y in range(570, 585, 2):
        px = img.getpixel((x, y))
        s = sum(px)
        if s > 300:
            print(f"  ({x},{y}): sum={s:3d} TEXT")

# Row 10 repo
print("\n=== ROW 10 REPO SCAN ===")
for x in range(160, 500, 10):
    for y in range(1060, 1085, 3):
        px = img.getpixel((x, y))
        s = sum(px)
        if s > 300:
            print(f"  ({x},{y}): sum={s:3d} TEXT")

# Row 20 repo
print("\n=== ROW 20 REPO SCAN ===")
for x in range(160, 500, 10):
    for y in range(1625, 1650, 3):
        px = img.getpixel((x, y))
        s = sum(px)
        if s > 300:
            print(f"  ({x},{y}): sum={s:3d} TEXT")

# Takeaways
print("\n=== TAKEAWAYS SCAN ===")
for x in range(70, 500, 20):
    for y in range(1760, 1820, 4):
        px = img.getpixel((x, y))
        s = sum(px)
        if s > 200:
            print(f"  ({x},{y}): sum={s:3d} TEXT")
